ALTER TABLE "knowledge"."kb_operations" ADD COLUMN "upload_job_id" uuid;--> statement-breakpoint
ALTER TABLE "knowledge"."kb_operations" ADD COLUMN "upload_queue_name" text;--> statement-breakpoint
ALTER TABLE "knowledge"."kb_operations" ADD CONSTRAINT "kb_operations_upload_job_check" CHECK (("knowledge"."kb_operations"."upload_job_id" IS NULL AND "knowledge"."kb_operations"."upload_queue_name" IS NULL) OR ("knowledge"."kb_operations"."upload_job_id" IS NOT NULL AND "knowledge"."kb_operations"."upload_queue_name" IS NOT NULL AND "knowledge"."kb_operations"."upload_queue_name" ~ '^[a-z][a-z0-9_]{0,62}$' AND "knowledge"."kb_operations"."kind" = 'upload' AND "knowledge"."kb_operations"."phase" <> 'uploading' AND "knowledge"."kb_operations"."target_version_id" IS NOT NULL));